INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laser Kitty Pow Pow', 'Cute? Maybe. Fast? Sure. Wild? You bet! Laser Kitty Pow Pow is the “purrfect” arcade game for vibrant, fast-paced, and easy to pick-up action. * Team up with a friend in a multiplayer mode exclusive to Nintendo Switch; * Fight more enemies than the highest number you know; * Enjoy explosions and satisfying action; * Unlock, use and upgrade special Cat-laser powers; * Meet Tim the Tailor and craft marvelous Cats; * Progress in an adaptive challenge system and face new enemies at your own pace; * Lose yourself in an over the top retro visual style. Choose your favorite Kitty and get ready for some serious Pow Pow!' FROM games WHERE igdb_id = 123347 ON CONFLICT (game_id, language_code) DO NOTHING;
