INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BattleSky Brigade: Harpooner', 'BattleSky Brigade Harpooner is a shoot’em up and “fishing” game. Shoot open barrels and enemies and avoid obstacles on the way up, like a classic vertical shoot em’ up! Reel yourself back in when you run out of rope and collect what you shot open! Set in the adorable world of BattleSky Brigade, help Pim on his quest to be the best salvager in all the Wyldes!' FROM games WHERE igdb_id = 122764 ON CONFLICT (game_id, language_code) DO NOTHING;
