INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sambaquis: A Story before Brazil', 'Sambaquis - A History Before Brazil is a game developed entirely by archaeologists and allows the player to experience the daily life within an indigenous group about 3000 years before the present in archaeological sites today denominated sambaquis (shellmounds). To perform the funeral of the Elder of your group, explore the ancient Brazilian landscape, talk to people and collect the necessary resources.' FROM games WHERE igdb_id = 216192 ON CONFLICT (game_id, language_code) DO NOTHING;
