INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guess My Word', 'A daily word guessing game that is an unofficial clone of one that used to be available on the website simbase.org. Players select a difficulty and attempt to guess a new mystery word each day, where each guess reveals whether the mystery word appears before or after the guess''s position in the dictionary. Leaderboards track the fastest finish times and the finishes with the fewest guesses. Players can also play through an archive of all previous days'' challenges.' FROM games WHERE igdb_id = 314418 ON CONFLICT (game_id, language_code) DO NOTHING;
