INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fork Parker''s Crunch Out', '"Fork Parker''s Crunch Out is a collaboration between Mega Cat Studios, Devolver Digital, and Take This for the label''s first-ever Super Nintendo Entertainment System release starring the company''s larger than life CFO, Fork Parker. The game aims to raise awareness of the all too real issue of game dev crunch through a playful look at the pressures of game development, exaggerated by the menace that is a game publisher executive."' FROM games WHERE igdb_id = 101155 ON CONFLICT (game_id, language_code) DO NOTHING;
