INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crazy-zen-mini-golf', 146934, '2019-12-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57d8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arad2.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Zen Mini Golf', 'Crazy Zen Mini Golf Marvellous Mystical Mini-Golf Madness! Experience the most mesmerising Mini-Golf game in the world! Explore the magical mini-golf madness as you adventure through our zany zen garden. Channel your inner zen in serene scenes and putt to perfection to complete all the holes in as few strokes as possible! Whether you’re playing individually or competing against friends, there’s endless fun to be had battling to beat the top score! Delve into this mind-blowing Mini-Golf world and marvel at the sensational gameplay to be had. Breathtakingly beautiful backdrops set the stage for exhilarating adventures amidst a realm of golfing glory! Collect coins to boost your chances of beating your opponent! Master the bouncing ball and jump to triumph! Select your swing strength, aim and shoot, taking the fastest route to the hole! Whizz your way around the colourful courses, wall-riding and mastering moving platforms whilst you swerve swinging pendulums and dive through Dragon’s mouths! As your skills skyrocket you’ll fly past the frothing fountains and prickly pyramids, bouncing off the bumpers and boost pads as you go! Grab this Mini-Golf mastery now to become the next putting Pro! Features include: Crazy courses Stunning scenery Awesome obstacles Varied 9 hole courses Multiplayer option Teleportation holes Jumping Ball Rainbow Ball' FROM games WHERE igdb_id = 146934 ON CONFLICT (game_id, language_code) DO NOTHING;
