INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Langrisser Mobile', 'Langrisser mobile retains the classic turn-based strategic gameplay of the original series, with class suppression, terrain effects, and unique class trees for a customizable battle experience. Featuring more than 300 classic levels, an unforgettable score by original series composer Noriyuki Iwadare, and all of the heroes from the main series, Langrisser fans, new and old alike, can experience the epic showdown between light and dark with other players around the world in real-time.' FROM games WHERE igdb_id = 106104 ON CONFLICT (game_id, language_code) DO NOTHING;
