INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sandwich-sudoku', 153572, '2019-08-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3bdv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar54gu.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sandwich Sudoku', 'In Sandwich Sudoku, the puzzle is presented with extra numbers outside the grid next to each row and column. These numbers indicate the SUM of cells sandwiched between the 1 and the 9 in that row/column. The logic required to solve the puzzles will appeal to anyone who enjoys normal sudoku and a bit of basic maths. Each puzzle here has been lovingly hand-crafted by Mark Goodliffe and Simon Anthony, the hosts of Cracking The Cryptic. They''ve even included their own hints on each puzzle to help if you get stuck. Mark and Simon have both represented the UK many times in the World Sudoku Championship.' FROM games WHERE igdb_id = 153572 ON CONFLICT (game_id, language_code) DO NOTHING;
