INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tanzer', 'Tänzer is a homebrew action title inspired by games like Strider, OSman and Hagane: The Final Conflict, the art of Keita Amemiya and Roger Dean, and anime series like Guyver. The protagonist is a ballet dancer who is unexpectedly hit by a bright purple light at night in an apartment, just a week before the premiere of the ballet version of The Ariane. After the character wakes up the body is transformed and the world is in chaos. Each level has a different setting, ranging from the Old West to Ancient Rome. Levels are made up of several stages with mini bosses and then a large boss at the end of the level, acting as the guardian of that era.' FROM games WHERE igdb_id = 103245 ON CONFLICT (game_id, language_code) DO NOTHING;
