INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World War Polygon', 'World War Polygon is a first-person shooter from WW2. When the world falls into the hell called war, it needs heroes who will stand against evil. World War Polygon allows you to be such a hero! The single player campaign is full of epic moments, story cutscenes and heroic deeds. Become a brave soldier that will go from D-Day in Normandy, through the Battle of Bulge in Ardennes and finally to Berlin. Experience also the Eastern Front in the skin of a Soviet soldier that will have to endure the Battle of Stalingrad and fight in Eastern Europe. Help ending the World War in 1945 during fall of Berlin as a part of allied military force.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 175693 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
