INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mega-mall-story-2', 146725, '2019-05-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8uyu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcmb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Mall Story 2', 'A business management sim where you can make a mall that''s right for you! Everything''s been expanded since the last game - build bigger, build higher! Enjoy more freedom and customization than ever. Add public transport stations to bring in customers from farther away. Visitors can come by bus, subway, helicopter, and even on UFOs! Meet new mall visitors bursting with personality. I could go for a bowl of ramen and a good book... It''s a manager''s job to make sure customers leave satisfied. Build stores that will delight your regulars! Create enough great stores... And you can even attract VIPs! New tenants stores exclusive to this title. Set up exhibitions, a movie theater, pool and even an indoor farm! Stores come in different shapes and sizes - the combinations are limitless! Create combos by placing related stores on the same floor. Take advantage of weather and scenery to attract more customers and compete with other stores to be the best mall in town! A new challenger steps into the world of business management, dreaming of one day running a 5-star mall... The sky''s the limit in Mega Mall Story 2! Try searching for "Kairosoft" to see all of our games!!' FROM games WHERE igdb_id = 146725 ON CONFLICT (game_id, language_code) DO NOTHING;
