INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burger Memory Game', 'A new way to train your brain with memory games. This time the challenge is to remember a picture list and not their position. First, you memorize all the images of fast food and then you match the cards in your kitchen. A fun game to help improve the concentration of children and adults.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 240919 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
